    $('developer-system-status').innerHTML=[['Provider',activeWorkspace.mode==='DEVICE'?'Waiting for device':providers.status],['Telemetry',activeWorkspace.mode==='DEVICE'?'NO DATA':connection],['Safety Engine',f.initializing?'Initializing':'Running'],['Last ingest',activeWorkspace.mode==='DEVICE'?'N/A':time(new Date(current.receivedAt||current.timestamp))]].map(([label,value])=>`<div><span>${label}</span><strong>${escape(value)}</strong></div>`).join('');
    $('developer-pipeline').innerHTML=['Source','Measurement Layer','Telemetry V1.1','Safety Engine','Application State'].map((label,index)=>`<div><span>${index+1}</span><strong>${label}</strong><small>${index===0?escape(source):index===2?'Contract validation':index===3?'Analysis active':'Ready'}</small></div>`).join('');
