    $('developer-safety-summary').innerHTML=[['Gas ppm',activeWorkspace.mode==='DEVICE'?'N/A':`${current.gas.value} ppm`],['Safety state',activeWorkspace.mode==='DEVICE'?'UNKNOWN':statusText(f.safety)],['Risk',activeWorkspace.mode==='DEVICE'?'N/A':`${f.risk}/100`],['Connection',activeWorkspace.mode==='DEVICE'?'NO DATA':connection]].map(([label,value])=>`<div><span>${label}</span><strong>${escape(value)}</strong></div>`).join('');
    $('developer-integrations').innerHTML=[['Simulation',activeWorkspace.mode==='SIMULATION'?'Active':'Isolated'],['REST',engine.state.source.restUrl?'Configured':'Not configured'],['MQTT',engine.state.source.mqttUrl?'Configured':'Not configured']].map(([label,value])=>`<div><strong>${label}</strong><span>${value}</span></div>`).join('');
    const readiness=integrationHealth?.readiness,overall=readiness?.overall||integrationStatus.STATES.NOT_CONFIGURED;$('integration-readiness-overall').textContent=overall==='READY_FOR_DEVICE'?'READY FOR DEVICE':overall==='ERROR'?'ERROR':'NEEDS CONFIGURATION';$('integration-readiness-overall').className=`gasguard-status-chip ${overall==='READY_FOR_DEVICE'?'is-ready':overall==='ERROR'?'is-error':''}`;$('integration-readiness-list').innerHTML=[['Server',readiness?.server||'UNAVAILABLE'],['LAN',readiness?.lan||'UNKNOWN'],['Ingress',readiness?.ingress||'UNAVAILABLE'],['Device Auth',readiness?.deviceAuth?.realConfigured?'CONFIGURED':'NOT CONFIGURED'],['Real Device',readiness?.realDevice||'WAITING_FOR_DEVICE'],['Virtual Test',readiness?.virtualTest||'NOT_CONFIGURED']].map(([label,value])=>`<div><span>${label}</span><strong>${escape(value.replaceAll('_',' '))}</strong></div>`).join('');
    $('reading-json').textContent=JSON.stringify(current,null,2);$('analysis-json').textContent=JSON.stringify(analysis,null,2);$('provider-state').innerHTML=[['Provider status',providers.status],['Provider message',providers.message],['Scenario',engine.state.scenario],['REST URL',engine.state.source.restUrl||'not configured'],['MQTT URL',engine.state.source.mqttUrl||'not configured'],['MQTT topic',engine.state.source.topic||'not configured']].map(x=>`<div><dt>${x[0]}</dt><dd>${escape(x[1])}</dd></div>`).join('');$('developer-events').innerHTML=engine.state.events.slice(0,10).map(e=>`<div class="developer-event"><strong>${escape(e.title)} · ${escape(incidentId(e))}</strong><span>${escape(e.eventType||e.type)} · ${escape(e.lifecycleStatus||'legacy')} · source ${escape(e.source||'legacy')}</span><code>${escape(`first ${e.firstReading?.lpgPpm??'null'} | latest ${e.latestReading?.lpgPpm??'null'} | peak ${e.peakLpgPpm??'null'} | readings ${e.readingCount??0} | rule ${e.prototypeRuleVersion||'legacy'}`)}</code></div>`).join('')||'<p>ยังไม่มี incident</p>';const selected=engine.state.events.find(e=>incidentId(e)===selectedIncidentId)||engine.state.events[0]||null;$('incident-evidence-json').textContent=JSON.stringify({ label:'UNVALIDATED_PROTOTYPE', selectedIncident:selected||null, currentUnknown:f.safety==='unknown', note:'Evidence is local prototype data; it is not a certified safety record.' },null,2);
