  function renderFloorPlan(){
    const plan=ensureFloorPlan(),recommendations=sensorRecommendations(plan),byCell=new Map(plan.entities.map(x=>[x.cell,x])),counts=Object.keys(planTypes).map(type=>[type,plan.entities.filter(x=>x.type===type)]),note=$('plan-editor-note');
    if(note)note.textContent=activePlanTool==='select'?(selectedPlanEntityId?'คลิกช่องว่างเพื่อย้ายจุดที่เลือก หรือคลิกจุดอื่นเพื่อเลือกใหม่':'คลิกองค์ประกอบเพื่อเลือก แล้วคลิกช่องว่างเพื่อย้าย'):`เครื่องมือ: ${activePlanTool==='clear'?'ลบทุกจุดในช่องที่คลิก':`เพิ่ม ${planTypes[activePlanTool].label} ในช่องว่าง`}`;
    $('floor-plan').innerHTML=Array.from({length:96},(_,cell)=>{const item=byCell.get(cell),classes=['plan-cell'];if(item)classes.push(`has-${item.type}`);if(item&&item.id===selectedPlanEntityId)classes.push('is-selected');if(!item&&recommendations.some(r=>r.cell===cell))classes.push('is-recommended');return `<button class="${classes.join(' ')}" data-plan-cell="${cell}" type="button" aria-label="ตำแหน่ง ${pointName(cell)}${item?` ${planTypes[item.type].label}`:''}">${item?`<span>${planTypes[item.type].short}</span>`:''}</button>`}).join('');
    $('plan-status').textContent=`${plan.entities.length} จุด · ${counts.find(x=>x[0]==='sensor')[1].length} sensor`;
    $('plan-facts').innerHTML=counts.map(([type,items])=>`<div><dt>${planTypes[type].label}</dt><dd>${items.length?items.map(x=>`${pointName(x.cell)}${x.placement==='recommended'?' · แนะนำ':''}`).join('<br>'):'ยังไม่วาง'}</dd></div>`).join('');
    $('plan-recommendations').innerHTML=recommendations.length?recommendations.map(r=>`<button type="button" class="recommendation-choice" data-add-recommendation="${r.cell}"><strong>${pointName(r.cell)} · ${r.score}/100</strong><span>${r.reason}</span></button>`).join(''):'<p>วางแหล่งแก๊สอย่างน้อย 1 จุดก่อนเพื่อคำนวณคำแนะนำ</p>';
    document.querySelectorAll('[data-plan-cell]').forEach(button=>button.addEventListener('click',()=>{
      const cell=Number(button.dataset.planCell),items=ensureFloorPlan().entities.slice(),existing=items.find(x=>x.cell===cell);
      if(activePlanTool==='select'){
        if(existing){selectedPlanEntityId=existing.id;renderFloorPlan();return;}
        const selected=items.find(x=>x.id===selectedPlanEntityId);if(!selected){toast('เลือกจุดที่จะย้ายก่อน','คลิกองค์ประกอบบนแปลน แล้วเลือกช่องว่างปลายทาง','warning');return;}selected.cell=cell;selected.placement='manual';persistPlan(items);toast('ย้ายตำแหน่งแล้ว',`${planTypes[selected.type].label} → ${pointName(cell)}`);render();return;
      }
      if(activePlanTool==='clear'){if(!existing){toast('ไม่มีจุดให้ลบ',pointName(cell),'warning');return;}selectedPlanEntityId=null;persistPlan(items.filter(x=>x.cell!==cell));toast('ลบองค์ประกอบแล้ว',pointName(cell));render();return;}
      if(existing){toast('ช่องนี้มีองค์ประกอบแล้ว','เลือกช่องว่าง หรือลบ/ย้ายจุดเดิมก่อน','warning');return;}
      items.push(entity(activePlanTool,cell,'manual',items.length+1));persistPlan(items);toast('เพิ่มองค์ประกอบแล้ว',`${planTypes[activePlanTool].label} · ${pointName(cell)}`);render();
    }));
    document.querySelectorAll('[data-add-recommendation]').forEach(button=>button.addEventListener('click',()=>addRecommendedSensor(Number(button.dataset.addRecommendation))));
  }
  function addRecommendedSensor(cell){const plan=ensureFloorPlan();if(plan.entities.some(x=>x.cell===cell)){toast('ตำแหน่งนี้ถูกใช้งานแล้ว',pointName(cell),'warning');return;}const items=plan.entities.concat(entity('sensor',cell,'recommended',plan.entities.length+1));persistPlan(items);toast('เพิ่ม Sensor ตามคำแนะนำแล้ว',`${pointName(cell)} · ยืนยันตำแหน่งจริงก่อนติดตั้ง`);render();}
  function pageTitles(page){return {overview:['SAFETY OVERVIEW',activeRole==='technician'?'ภาพรวมช่าง':'ภาพรวมความปลอดภัย'],demo:['DEVELOPER DEMO CONTROL','ศูนย์ควบคุมการจำลอง'],live:['DEVICE DIAGNOSTICS','อุปกรณ์และวินิจฉัย'],intelligence:['FEATURE ANALYSIS','Feature Analysis'],replay:['EVENT REVIEW','ตรวจสอบเหตุการณ์'],validation:['RULE / MODEL VALIDATION','ทดสอบระบบ'],spatial:['SPATIAL SIMULATION','จำลองการกระจาย LPG'],analytics:['ANALYTICS','การวิเคราะห์ข้อมูล'],events:['LOGS AND EVIDENCE','เหตุการณ์และหลักฐาน'],alerts:['ALERT CENTER','การแจ้งเตือน'],guide:['HELP','ความช่วยเหลือ'],devices:['DEVICES','อุปกรณ์'],maintenance:['MAINTENANCE','การบำรุงรักษา'],assistant:['HELP','Ask GasGuard'],locations:['AREA','พื้นที่'],reports:['SERVICE REPORT','รายงานการบริการ'],settings:['VERSION AND CONFIGURATION','Version and Configuration'],explorer:['DATA EXPLORER','Data Explorer'],developer:['SYSTEM OVERVIEW','System Overview'],'hardware-lab':['HARDWARE INTEGRATION','Hardware Integration Lab'],'admin-dashboard':['PLATFORM ADMINISTRATION','Admin Dashboard'],product:['PRODUCT & TECHNOLOGY','Product & Technology']}[page]||['GASGUARD','GasGuard'];}
