  function renderMobileNavigation(){const target=$('mobile-navigation'),moreList=$('mobile-more-list');if(!target||!moreList)return;const primary=navigation.primaryFor(activeRole),visible=primary.slice(0,4),more=primary.slice(4).concat(navigation.moreFor(activeRole)),moreLabel='เพิ่มเติม';target.innerHTML=`${visible.map(item=>`<button class="mobile-nav-item ${activePage===item.page?'is-active':''}" data-mobile-page="${escape(item.page)}" type="button" aria-current="${activePage===item.page?'page':'false'}"><span aria-hidden="true">${item.icon}</span><span>${escape(item.label)}</span></button>`).join('')}<button class="mobile-nav-item ${more.some(item=>item.page===activePage)?'is-active':''}" id="open-mobile-more" type="button" aria-haspopup="dialog"><span aria-hidden="true">•••</span><span>${moreLabel}</span></button>`;moreList.innerHTML=more.map(item=>`<button class="mobile-more-item" data-mobile-more-page="${escape(item.page)}" type="button"><span aria-hidden="true">${item.icon}</span><span>${escape(item.label)}</span></button>`).join('');$('mobile-scenario-select').value=window.GasGuardDemoScenario||'NORMAL';target.querySelectorAll('[data-mobile-page]').forEach(button=>button.addEventListener('click',()=>openNavigationEntry(visible.find(item=>item.page===button.dataset.mobilePage))));moreList.querySelectorAll('[data-mobile-more-page]').forEach(button=>button.addEventListener('click',()=>{const entry=more.find(item=>item.page===button.dataset.mobileMorePage);$('mobile-more-sheet').close();openNavigationEntry(entry);}));$('open-mobile-more').addEventListener('click',()=>$('mobile-more-sheet').showModal());}
  function goToPage(page){page=navigation.resolvePage(activeRole,page);activePage=page;document.querySelectorAll('.page').forEach(section=>section.classList.toggle('is-visible',section.id===`page-${page}`));const title=pageTitles(page);$('page-kicker').textContent=title[0];$('page-title').textContent=title[1];try{localStorage.setItem(PAGE_KEY,activePage)}catch(e){}renderNavigation();window.GasGuardDemoRefresh?.();}
  function applyRole(role){if(!roleNavigation[role])return false;activeRole=role;document.body.dataset.authRole=role;document.body.classList.remove('general-role','technician-role','developer-role','admin-role','owner-mode');document.body.classList.add(`${activeRole}-role`);activePage=navigation.landingFor(activeRole);goToPage(activePage);render();return true;}
  function renderRoleContext(f){const provisioned=Boolean(setupProfile.name&&setupProfile.savedAt),siteName=activeWorkspace.mode==='DEVICE'?activeWorkspace.name:(provisioned?setupProfile.name:'ยังไม่ได้ลงทะเบียนสถานที่'),source=activeWorkspace.mode==='DEVICE'?activeWorkspace.label:engine.state.source.mode==='simulation'?'ข้อมูลจำลอง · Simulation':engine.state.source.mode==='rest'?'ข้อมูลจาก REST · Prototype':'ข้อมูลจาก MQTT · Prototype';$('site-context').textContent=`Workspace: ${siteName}${activeWorkspace.mode==='SIMULATION'&&!provisioned?' · พื้นที่ตัวอย่าง Restaurant A':''}`;$('data-source-badge').textContent=source;$('data-source-badge').classList.toggle('is-live',activeWorkspace.mode==='SIMULATION'&&engine.state.source.mode!=='simulation');$('workspace-badge').innerHTML=`<strong>${escape(activeWorkspace.name)}</strong><small>${escape(workspaceState.status.replaceAll('_',' '))}</small>`;renderGeneralLanding(f,siteName,provisioned);}
