  function renderWorkspaceBoundary(){const deviceMode=activeWorkspace.mode==='DEVICE',test=activeWorkspace.source==='TEST_DEVICE';document.body.classList.toggle('workspace-waiting',deviceMode);$('workspace-boundary').hidden=!deviceMode;if(!deviceMode)return;$('workspace-boundary-label').textContent=test?'TEST DATA · VIRTUAL DEVICE':workspaceState.dataClassification==='SYNTHETIC_HANDSHAKE'?'HARDWARE PILOT · SYNTHETIC HANDSHAKE':'HARDWARE PILOT · REAL DEVICE';$('workspace-boundary-title').textContent=workspaceState.connection==='ONLINE'?(test?'Virtual device connected':'Device connected'):'Waiting for device';$('workspace-boundary-copy').textContent=test?'ข้อมูลทั้งหมดใน workspace นี้มาจาก Virtual ESP32 ผ่าน HTTP ingress เดียวกับอุปกรณ์จริง และไม่ถูกนับรวมกับ Hardware Pilot':workspaceState.dataClassification==='SYNTHETIC_HANDSHAKE'?'แพ็กเก็ตนี้ใช้ค่าทดสอบคงที่เพื่อยืนยัน WiFi และ HTTP path เท่านั้น ไม่ใช่ค่าจาก gas sensor':'ระบบจะแสดงข้อมูลเมื่อได้รับ telemetry ที่ยืนยัน device credential และ registry แล้วเท่านั้น ไม่มี simulation fallback';$('workspace-boundary-facts').innerHTML=hardwareFacts({'Device connection':workspaceState.connection||'WAITING_FOR_DEVICE','Last telemetry':workspaceState.lastTelemetry||'N/A',Sensors:(workspaceState.sensors?.length?workspaceState.sensors:activeWorkspace.expectedSensors).join(', '),'Ingress status':workspaceState.ingress||'READY','Data classification':workspaceState.dataClassification||'N/A',Scenario:test?(workspaceState.scenario||'N/A'):'N/A','Packet status':workspaceState.packetStatus||'NO DATA','Safety state':workspaceState.safety||'UNKNOWN','Gas ppm':workspaceState.gasPpm??'N/A'});}
